        'ms365_blurb' => 'Entra ID से लोग, ग्रुप और मैनेजर, और Intune से डिवाइस उनके उपयोगकर्ताओं और ऐप्स के साथ - FreeITSM आपके Microsoft टेनेंट से यही पढ़ता है।',
        'ms365_subtitle' => 'FreeITSM आपके Microsoft टेनेंट से क्या पढ़ता है। Entra ID और Intune अलग-अलग कनेक्शन हैं - अक्सर Entra में एक ही ऐप रजिस्ट्रेशन से जुड़े होते हैं।',
        'ms365_entra_heading' => 'Entra ID - लोग, ग्रुप और मैनेजर',
        'ms365_entra_intro' => 'किसी के साइन इन करने से पहले लोगों, उनके ग्रुप और कौन किसे मैनेज करता है, इम्पोर्ट करता है। हर Entra ID साइन-इन का अपना इम्पोर्ट होता है।',
        'ms365_entra_none' => 'अभी कोई Entra ID साइन-इन सेट अप नहीं है। लोगों का इम्पोर्ट उसी के साथ आता है: पहले Authentication में Microsoft Entra ID जोड़ें।',
        'ms365_importing' => 'लोगों को इम्पोर्ट कर रहा है',
