        'ms365_open_signin' => 'साइन-इन',
        'ms365_signin_note' => 'Entra ID से साइन इन करना अन्य साइन-इन तरीकों के साथ System -> Authentication में ही रहता है।',
        'ms365_intune_heading' => 'Intune - डिवाइस, उनके प्राइमरी उपयोगकर्ता और ऐप्स',
        'ms365_intune_intro' => 'Intune के डिवाइस एसेट बन जाते हैं, जो उनके प्राइमरी उपयोगकर्ता के पास रखे जाते हैं, उनके इंस्टॉल किए गए ऐप्स के साथ। इसे यहाँ सेट अप करें; यह पहले Assets -> Settings -> Intune में था।',
        'ms365_job_last' => '{job}: {when}, {outcome}',
        'ms365_job_never' => '{job}: कभी नहीं चला',
        'ms365_more_heading' => 'Microsoft से और भी',
        'ms365_more_intro' => 'बाकी सब कुछ जो Microsoft 365 से बात करता है। हर एक वहीं सेट अप होता है जहाँ वह आता है - बटन उसे वहाँ खोलता है - और यहाँ सूचीबद्ध है ताकि सब कुछ एक जगह रहे।',
