        'ms365_intune_conn_subtitle' => 'कौन सा Microsoft टेनेंट, और कौन सा ऐप रजिस्ट्रेशन उसके डिवाइस पढ़ता है। क्या इम्पोर्ट होता है, यह इम्पोर्ट टैब में सेट होता है।',
        'ms365_intune_import_subtitle' => 'कनेक्शन क्या लाता है: डिवाइस एसेट के रूप में, हर तरह के डिवाइस का एसेट प्रकार, और उनके इंस्टॉल किए गए ऐप्स।',
        'ms365_intune_next_import' => 'अगला',
        'ms365_intune_assets_off' => 'Intune डिवाइस को एसेट के रूप में लाता है, और इस इंस्टॉलेशन के लिए Assets बंद है। Intune सेट अप करने के लिए इसे System -> Modules में चालू करें।',
        'ms365_intune_tab_devices' => 'डिवाइस',
        'ms365_intune_tab_types' => 'एसेट प्रकार',
        'ms365_intune_tab_software' => 'सॉफ़्टवेयर',
        'ms365_intune_devices_intro' => 'हर Intune डिवाइस एसेट बन जाता है, या जिस एसेट से जुड़ा है उसे अपडेट करता है। ये तय करते हैं कि वह किस कंपनी का है और सिंक उस पर क्या बदल सकता है।',
        'ms365_intune_save_hint' => 'सभी टैब सहेजता है। कनेक्शन अपने पेज पर अलग से सहेजा जाता है।',
        'ms365_intune_device_sync' => 'डिवाइस सिंक',
        'ms365_open_intune_conn' => 'कनेक्शन',
        'ms365_open_intune_import' => 'इम्पोर्ट',
        'zabbix_blurb' => 'मॉनिटरिंग की समस्याएँ अपने आप घटनाएँ खोलती हैं, दोहराव उनमें जुड़ते हैं, और रिकवरी उन्हें हल कर देती है।',
        'zabbix_intro' => 'जब Zabbix को कोई समस्या मिलती है - डिस्क भरती हुई, सर्वर जवाब नहीं देता - तो वह यहाँ एक घटना दर्ज करता है, जो CMDB में उस सर्वर से जुड़ी होती है। अगर वह वही समस्या फिर रिपोर्ट करे, तो वह उसी टिकट पर जाती है। समस्या ठीक होने पर टिकट हल हो जाता है।',
        'zabbix_direction' => 'Zabbix FreeITSM को कॉल करता है - FreeITSM कभी Zabbix से कनेक्ट नहीं होता, इसलिए उसे Zabbix का पता या Zabbix पासवर्ड नहीं चाहिए। Zabbix को जो कुछ चाहिए वह नीचे है।',
        'zabbix_not_ready' => 'पहले System → Database Verification चलाएँ: वह वह तालिका बनाता है जिसमें यह इंटीग्रेशन अपना इवेंट लॉग रखता है।',
        'zabbix_connect' => 'Zabbix कनेक्ट करें',
        'zabbix_connect_body' => 'Zabbix हर अलर्ट सीक्रेट टोकन के साथ नीचे दिए पते पर भेजता है। Zabbix में Alerts → Media types → Create media type पर जाएँ, Webhook चुनें, नाम FreeITSM रखें, नीचे दिए पैरामीटर और स्क्रिप्ट पेस्ट करें, फिर उसे किसी उपयोगकर्ता और Alerts → Actions → Trigger actions के किसी एक्शन में जोड़ें। एक्शन में "Recovery operations" पर टिक करें, वरना टिकट कभी हल नहीं होंगे।',
        'zabbix_endpoint' => 'FreeITSM का पता (यह Zabbix को दें)',
        'zabbix_import' => 'सबसे तेज़: इसे Zabbix में इम्पोर्ट करें',
        'zabbix_import_body' => 'सब कुछ भरा हुआ मीडिया टाइप डाउनलोड करें - ऊपर का पता, आपका टोकन, स्क्रिप्ट और तीन मैसेज टेम्पलेट - फिर Zabbix में Alerts → Media types → Import पर जाएँ और फ़ाइल चुनें। इसके बाद इसे किसी उपयोगकर्ता को दें और एक एक्शन जोड़ें (गाइड का चरण 4)।',
        'zabbix_import_download' => 'Zabbix इम्पोर्ट के लिए डाउनलोड करें',
        'zabbix_import_needs_token' => 'पहले एक टोकन बनाएँ - फ़ाइल में वही रहता है।',
        'zabbix_by_hand' => 'या इसे हाथ से सेट अप करें',
        'zabbix_token' => 'टोकन',
        'zabbix_token_none' => 'अभी कोई टोकन नहीं - इंटीग्रेशन चालू करने के लिए एक बनाएँ।',
        'zabbix_token_make' => 'टोकन बनाएँ',
        'zabbix_token_rotate' => 'नया टोकन',
        'zabbix_rotate_confirm' => 'नया टोकन बनाएँ? पुराना तुरंत काम करना बंद कर देगा, इसलिए जब तक आप नया टोकन उसके मीडिया टाइप में पेस्ट नहीं करते, Zabbix विफल रहेगा।',
        'zabbix_params' => 'मीडिया टाइप पैरामीटर',
        'zabbix_params_hint' => 'नए वेबहुक के लिए Zabbix जो पैरामीटर भरता है (URL, HTTPProxy, To, Subject, Message) उन्हें हटा दें - वे उसकी उदाहरण स्क्रिप्ट के हैं, इसकी नहीं। फिर यहाँ की हर लाइन को एक पैरामीटर के रूप में जोड़ें: बाईं ओर नाम, दाईं ओर मान। http_proxy खाली रहता है जब तक आपका Zabbix सर्वर FreeITSM तक केवल प्रॉक्सी से न पहुँच सके। ब्रेसिज़ में दिए मान Zabbix मैक्रो हैं - उन्हें जैसा है वैसा रहने दें। url लाइन हर टिकट को Zabbix में समस्या से वापस जोड़ने वाला लिंक देती है; इसके लिए मैक्रो {$ZABBIX.URL} आपके Zabbix वेब पते पर सेट होना चाहिए (Zabbix: Administration → Macros)। इसके बिना टिकटों पर बस कोई लिंक नहीं होता।',
        'zabbix_script' => 'मीडिया टाइप स्क्रिप्ट',
        'zabbix_copy' => 'कॉपी करें',
        'zabbix_copied' => 'कॉपी हो गया।',
        'zabbix_reach_hint' => 'जहाँ Zabbix अलर्ट भेजेगा। यह आपके सार्वजनिक बेस URL से शुरू होता है; अगर Zabbix उसी सर्वर या नेटवर्क पर है, तो FreeITSM तक उसका रास्ता अलग हो सकता है - इसी मशीन पर Docker में चल रहे Zabbix के लिए http://host.docker.internal/ और बाकी पाथ। इसे यहाँ बदलें और पैरामीटर तथा डाउनलोड उसके अनुसार बदल जाएँगे।',
        'zabbix_tickets' => 'यह जो घटनाएँ दर्ज करता है',
        'zabbix_requester' => 'इस रूप में दर्ज',
        'zabbix_requester_hint' => 'वह अनुरोधकर्ता जिससे टिकट आते हैं। डिफ़ॉल्ट कभी मेल प्राप्त नहीं कर सकता, इसलिए अलर्ट के बारे में किसी को ईमेल नहीं जाता; अगर आप चाहते हैं कि पावती कहीं भेजी जाए तो असली मॉनिटरिंग मेलबॉक्स का उपयोग करें।',
        'zabbix_requester_name' => 'अनुरोधकर्ता का नाम',
        'zabbix_company' => 'कंपनी',
        'zabbix_company_hint' => 'तब उपयोग होती है जब सर्वर CMDB में नहीं है, या उसके CMDB आइटम में कोई कंपनी नहीं है। जो सर्वर CMDB में है, वह अपनी कंपनी में जाता है।',
        'zabbix_team' => 'टीम',
        'zabbix_origin' => 'स्रोत',
        'zabbix_none' => '(कोई नहीं)',
        'zabbix_priority_map' => 'गंभीरता → प्राथमिकता',
        'zabbix_priority_hint' => 'हर Zabbix गंभीरता के लिए नई घटना को कौन सी प्राथमिकता मिलती है।',
        'zabbix_resolve' => 'जब समस्या ठीक हो जाए',
        'zabbix_resolve_leave' => 'स्थिति को न छुएँ',
        'zabbix_resolve_hint' => 'टिकट में "recovered" संदेश हमेशा जोड़ा जाता है। यह तय करता है कि उसकी स्थिति भी बदले या नहीं।',
        'zabbix_link_cmdb' => 'Zabbix होस्ट के नाम वाले CMDB आइटम को लिंक करें',
        'zabbix_link_cmdb_hint' => 'पहले पूरा नाम, फिर छोटा नाम (web01.example.com के लिए web01)। अगर दो कंपनियों में मेल मिलता है, तो कोई लिंक नहीं होता।',
        'zabbix_saved' => 'सहेजा गया।',
        'zabbix_events' => 'हाल के अलर्ट',
        'zabbix_events_none' => 'अभी तक कुछ प्राप्त नहीं हुआ। Zabbix के भेजते ही अलर्ट यहाँ दिखेंगे।',
        'zabbix_col_when' => 'प्राप्त हुआ',
        'zabbix_col_host' => 'होस्ट',
        'zabbix_col_problem' => 'समस्या',
        'zabbix_col_severity' => 'गंभीरता',
        'zabbix_col_result' => 'परिणाम',
        'zabbix_col_ticket' => 'टिकट',
        'zabbix_act_created' => 'घटना दर्ज हुई',
        'zabbix_act_updated' => 'टिकट में जोड़ा गया',
        'zabbix_act_resolved' => 'रिकवर हुआ',
        'zabbix_act_recovery_unmatched' => 'बिना टिकट वाली रिकवरी',
        'zabbix_act_error' => 'विफल',
        'zabbix_recovery' => 'रिकवरी',
        'zabbix_test' => 'आज़माएँ',
        'zabbix_test_body' => 'इंटीग्रेशन के ज़रिए एक टेस्ट समस्या भेजता है, ठीक वैसे ही जैसे Zabbix का असली अलर्ट संभाला जाता है: आपकी सेटिंग्स के साथ एक घटना दर्ज होती है, और फिर आप उसकी रिकवरी भेजकर देख सकते हैं कि वह कैसे हल होती है। टेस्ट घटना बनी रहती है, टेस्ट के शीर्षक के साथ, ताकि आप देख सकें कि असली कैसी दिखती है - इसे किसी भी अन्य टिकट की तरह बंद करें।',
        'zabbix_test_limit' => 'यह FreeITSM वाले हिस्से को जाँचता है। आपका Zabbix सर्वर FreeITSM तक पहुँच सकता है या नहीं, यह दूसरा हिस्सा है: इसे Zabbix में मीडिया टाइप के Test बटन से जाँचें।',
        'zabbix_test_send' => 'टेस्ट अलर्ट भेजें',
        'zabbix_test_recover' => 'रिकवरी भेजें',
        'zabbix_test_raised' => 'टेस्ट घटना {ticket} दर्ज हुई।',
        'zabbix_test_resolved' => 'रिकवरी प्राप्त हुई - {ticket} हल हो गया।',
        'zabbix_test_failed' => 'टेस्ट विफल रहा: {error}',
        'zabbix_test_trigger' => 'FreeITSM से टेस्ट अलर्ट',
        'zabbix_test_message' => 'यह System → Integrations → Zabbix से भेजा गया टेस्ट है। कुछ भी गड़बड़ नहीं है।',
        'msteams_blurb' => 'आपके Teams चैनलों में कार्ड के रूप में सर्विस डेस्क अलर्ट - अर्जेंट टिकट, SLA उल्लंघन, हर टीम के टिकट - टिकट तक सीधे जाने वाले बटन के साथ।',
        'msteams_intro' => 'सर्विस डेस्क अलर्ट Microsoft Teams चैनलों में कार्ड के रूप में पोस्ट करें, हर एक में Open in FreeITSM बटन के साथ। टिक करें कि हर चैनल को किस बारे में सुनना चाहिए: अर्जेंट टिकट, SLA चेतावनियाँ और उल्लंघन, उसकी टीमों के टिकट, स्टेटस पेज घटनाएँ, प्रतीक्षारत अनुमोदन।',
        'msteams_not_ready' => 'पहले System → Database Verification चलाएँ: वह वे तालिकाएँ बनाता है जिनमें ये अलर्ट रखे जाते हैं।',
        'msteams_bot_h' => 'Teams चैट बॉट',
        'msteams_bot_body' => 'यह पेज केवल अलर्ट पोस्ट करता है। लोग Teams में सर्विस डेस्क से चैट कर सकें - हर बातचीत एक टिकट - इसके लिए Tickets → Settings → Messaging में Teams बॉट सेट अप करें।',
        'msteams_bot_count' => '{n} Teams बॉट चैनल सेट अप हैं।',
        'msteams_bot_link' => 'Messaging सेटिंग्स खोलें',
        'msteams_how_h' => 'चैनल का वेबहुक पता पाएँ',
        'msteams_how_body' => 'Teams में चैनल खोलें, उसके नाम के आगे … पर क्लिक करें, फिर Workflows। "Post to a channel when a webhook request is received" चुनें, चरणों का पालन करें, और अंत में मिलने वाला पता कॉपी करें। उसे नीचे किसी चैनल में पेस्ट करें। यह पता पासवर्ड की तरह काम करता है: जिसके पास भी यह है वह उस चैनल में पोस्ट कर सकता है, इसलिए यह एन्क्रिप्टेड रखा जाता है और दोबारा कभी नहीं दिखाया जाता।',
        'msteams_channels_h' => 'चैनल',
        'msteams_channels_none' => 'अभी कोई चैनल नहीं। अलर्ट पाने वाले हर Teams चैनल के लिए एक जोड़ें।',
        'msteams_add' => 'जोड़ें',
