        'msteams_workflows_note' => 'टिक किया गया हर अलर्ट Workflows पेज पर "Teams: …" नाम का एक वर्कफ़्लो है, जहाँ उसका इतिहास और डिलीवरी हैं। बदलाव यहीं करें: वहाँ किया गया संपादन इस चैनल को अगली बार सहेजने पर बदल दिया जाता है।',
