        'msteams_delete_confirm' => 'इस चैनल और इसके बनाए वर्कफ़्लो को हटाएँ? उनका इतिहास Workflows पेज पर बना रहता है।',
        'msteams_needs_name' => 'चैनल को एक नाम दें।',
        'threecx_blurb' => 'जवाब देने से पहले देखें कि कौन कॉल कर रहा है, हर कॉल को कॉलर के टिकट पर रखें, और एक क्लिक में नंबर डायल करें।',
        'threecx_intro' => 'जब कॉल की घंटी बजती है, तो 3CX FreeITSM से पूछता है कि नंबर किसका है और कॉलर का नाम दिखाता है - और विश्लेषक के लिए उनका टिकट खोलता है। कॉल खत्म होने पर, उस टिकट पर नोट जुड़ जाता है, जो कॉल लेने वाले विश्लेषक के नाम से लिखा होता है। टिकटों और लोगों पर फ़ोन नंबर भी 3CX के ज़रिए डायल किए जा सकते हैं।',
        'threecx_direction' => '3CX FreeITSM को कॉल करता है - FreeITSM कभी 3CX से कनेक्ट नहीं होता, इसलिए उसे आपके फ़ोन सिस्टम का पता या 3CX पासवर्ड नहीं चाहिए। 3CX को जो कुछ चाहिए वह नीचे दिए टेम्पलेट में है।',
        'threecx_not_ready' => 'पहले System → Database Verification चलाएँ: वह वह तालिका बनाता है जिसमें यह इंटीग्रेशन अपना कॉल लॉग रखता है।',
        'threecx_connect' => '3CX कनेक्ट करें',
        'threecx_connect_body' => '3CX, CRM टेम्पलेट के ज़रिए FreeITSM से जुड़ता है। एक टोकन बनाएँ, टेम्पलेट डाउनलोड करें, और 3CX Admin Console में Integrations → CRM के अंतर्गत उसे अपलोड करें। 3CX नीचे दिए पते तक पहुँचने में सक्षम होना चाहिए।',
        'threecx_endpoint' => 'FreeITSM का पता, जैसे 3CX उस तक पहुँचेगा',
        'threecx_reach_hint' => 'यह आपके सार्वजनिक बेस URL से शुरू होता है। 3CX अक्सर क्लाउड में होता है, इसलिए यह ऐसा पता होना चाहिए जहाँ इंटरनेट पहुँच सके। इसे यहाँ बदलें और डाउनलोड उसके अनुसार बदल जाएगा।',
        'threecx_token' => 'टोकन',
        'threecx_token_none' => 'अभी कोई टोकन नहीं - इंटीग्रेशन चालू करने के लिए एक बनाएँ।',
        'threecx_token_make' => 'बनाएँ',
        'threecx_token_rotate' => 'बदलें',
        'threecx_rotate_confirm' => 'नया टोकन बनाएँ? जब तक आप टेम्पलेट दोबारा अपलोड नहीं करते (या उसमें नया टोकन पेस्ट नहीं करते), 3CX FreeITSM तक पहुँचना बंद कर देगा।',
        'threecx_copy' => 'कॉपी करें',
        'threecx_copied' => 'कॉपी हो गया।',
        'threecx_download' => 'डाउनलोड करें',
        'threecx_download_body' => 'अपलोड के लिए तैयार टेम्पलेट: पता, यह टोकन, कॉलर लुकअप और कॉल रिपोर्ट। इसमें टोकन है, इसलिए फ़ाइल को अपने तक रखें।',
        'threecx_download_needs_token' => 'पहले एक टोकन बनाएँ - टेम्पलेट में वही रहता है।',
