        'threecx_rule_hint' => 'कॉल की घंटी बजने पर 3CX विश्लेषक के लिए जो टिकट खोलता है, वह भी इसी चुनाव का पालन करता है।',
        'threecx_create' => 'बिना खुले टिकट वाले व्यक्ति की कॉल के लिए नया टिकट खोलें',
        'threecx_create_unknown' => 'उन नंबरों के लिए भी जो FreeITSM में किसी के पास नहीं हैं',
        'threecx_create_hint' => 'केवल आने वाली कॉल (उठाई गई या छूटी) के लिए। कॉल लेने वाले विश्लेषक को सौंपा जाता है। अज्ञात कॉलर को "Caller" और उनके नंबर के रूप में दर्ज किया जाता है, ताकि उसे सही व्यक्ति से जोड़ा जा सके।',
        'threecx_fallback' => 'जब 3CX उपयोगकर्ता विश्लेषक नहीं है, तब नोट इस रूप में लिखें',
        'threecx_fallback_hint' => 'नोट उस विश्लेषक के नाम से लिखा जाता है जिसका ईमेल कॉल लेने वाले 3CX उपयोगकर्ता से मेल खाता है। जब कोई मेल नहीं खाता - रिसेप्शनिस्ट, साझा फ़ोन - तब वह इस विश्लेषक के नाम से लिखा जाता है, यह बताते हुए कि किसने कॉल ली। किसी को न चुनने पर, वे कॉल केवल नीचे सूचीबद्ध होती हैं।',
        'threecx_nobody' => 'कोई नहीं',
        'threecx_company' => 'अज्ञात नंबरों के टिकटों के लिए कंपनी',
        'threecx_company_hint' => 'जाने-पहचाने कॉलर का टिकट उनकी अपनी कंपनी में जाता है।',
        'threecx_team' => 'नए टिकटों के लिए टीम',
        'threecx_origin' => 'नए टिकटों के लिए स्रोत',
        'threecx_none' => 'कोई नहीं',
        'threecx_dial_h' => 'क्लिक-टू-कॉल',
        'threecx_dial_body' => 'टिकटों, Tickets → Users और People पर फ़ोन नंबरों को Call बटन मिलता है जो आपके फ़ोन के ज़रिए डायल करता है। यह विश्लेषक के अपने कंप्यूटर पर खुलता है, जहाँ वे पहले से 3CX में साइन इन हैं, इसलिए FreeITSM को उनका एक्सटेंशन कभी नहीं चाहिए।',
        'threecx_dial' => 'डायल पता',
        'threecx_dial_hint' => 'जहाँ नंबर जाना है वहाँ {number} रखें। 3CX वेब क्लाइंट के लिए: https://your-pbx.3cx.com/webclient/#/call?phone={number}। 3CX डेस्कटॉप ऐप (या किसी भी सॉफ़्टफ़ोन) के लिए: tel:{number}। Call बटन बंद करने के लिए इसे खाली छोड़ें।',
