        'configured' => 'कॉन्फ़िगर किया गया',
        'not_configured' => 'सेटअप नहीं है',
        'tika_blurb' => 'PDF, पुरानी Office फ़ाइलों और स्कैन किए गए दस्तावेज़ों के अंदर का टेक्स्ट पढ़ें ताकि उन्हें खोजा जा सके।',
        'tika_intro' => 'FreeITSM को एक दस्तावेज़-पठन सेवा से जोड़ता है। Word, Excel, PowerPoint और plain text फ़ाइलें इसके बिना भी पहले से खोजी जाती हैं; Tika वे फ़ॉर्मेट जोड़ता है जिन्हें FreeITSM खुद नहीं पढ़ सकता।',
        'tika_security_title' => 'इसे नेटवर्क से दूर रखें',
        'tika_security_body' => 'Tika में न कोई पासवर्ड है न किसी तरह का प्रमाणीकरण: जो भी इस तक पहुँच सकता है वह इसे भेजी गई कोई भी फ़ाइल पढ़ लेगा। इसे इस तरह चलाएँ कि केवल यह सर्वर ही इससे बात कर सके — 127.0.0.1 से बाइंड करके, या किसी private container नेटवर्क पर — और इसका पोर्ट कभी इंटरनेट पर उजागर न करें।',
