        'slack_step1' => 'Slack में, <strong>api.slack.com/apps</strong> पर जाएँ और <strong>Create New App → From a manifest</strong> चुनें। जिस workspace में आप service desk चाहते हैं वह चुनें।',
        'slack_step2' => 'यह manifest पेस्ट करें। यह नाम, अनुमतियाँ, और वह पता तय करता है जिस पर Slack संदेश भेजता है, इसलिए हाथ से कुछ भी टिक करने की ज़रूरत नहीं है।',
        'slack_step3' => '<strong>Install to Workspace</strong> पर क्लिक करें और इसे स्वीकृत करें। फिर <strong>Bot User OAuth Token</strong> और <strong>Signing Secret</strong> वापस यहाँ Edit फ़ॉर्म में कॉपी करें — Slack token दोबारा नहीं दिखाएगा। <strong>अगर Slack पीला &ldquo;Reinstall to Workspace&rdquo; बैनर दिखाए, तो पहले उस पर क्लिक करें</strong> — वरना token में ज़्यादातर अनुमतियाँ नहीं होंगी और टिकट बिना भेजने वाले के नाम के आएँगे।',
        'slack_step4' => 'जाँचें कि नीचे दिया गया request URL <strong>Event Subscriptions</strong> के अंतर्गत Slack में दिखने वाले URL से मेल खाता है। Slack app सहेजते ही इसे सत्यापित करता है, इसलिए यह सर्वर इंटरनेट से पहुँच योग्य होना चाहिए।',
        'slack_step5' => 'Slack में, app को उस चैनल में आमंत्रित करें जिस पर आप इसे नज़र रखवाना चाहते हैं: <strong>/invite @YourApp</strong>. यह उस चैनल को नहीं पढ़ सकता जिसमें यह नहीं है।',
