        'err_invalid_host' => 'यह मान्य नाम नहीं है। केवल अक्षर, संख्याएँ, हाइफ़न और बिंदु इस्तेमाल करें, जैसे freeitsm.internal।',
        'err_invalid_ip' => 'यह मान्य IP पता नहीं है।',
        'err_not_persisted' => 'पहले इस पेज के ऊपर बताया Docker बदलाव करें।',
        'err_generic' => 'प्रमाणपत्र नहीं बनाया जा सका: {error}',
        'steps_heading' => 'आगे क्या करें',
        'step_dns_title' => 'नाम को सर्वर की ओर इंगित करें',
        'step_dns_body' => 'PC को पता होना चाहिए कि {host} का मतलब {ip} है। सबसे अच्छा तरीका आपके नेटवर्क के DNS सर्वर पर DNS रिकॉर्ड बनाना है (Windows डोमेन में DNS Manager में; छोटे नेटवर्क में अक्सर राउटर में):',
        'step_dns_record' => 'Type A, name {host}, address {ip}',
        'step_dns_hosts' => 'DNS सर्वर न हो तो हर PC की hosts फ़ाइल में यह पंक्ति जोड़ें (Windows पर {path}, Mac पर {path_mac}):',
        'step_dns_no_ip' => 'बनाया जाने वाला सटीक रिकॉर्ड देखने के लिए ऊपर सर्वर का IP पता भरें।',
        'step_ca_title' => 'हर PC पर अथॉरिटी प्रमाणपत्र इंस्टॉल करें',
        'step_ca_body' => 'इससे PC प्रमाणपत्र पर भरोसा करने लगते हैं। इसे हर PC पर केवल एक बार करना होता है, और दोबारा तभी जब आप नाम या IP बदलें।',
        'download' => 'डाउनलोड करें',
        'step_ca_windows' => 'Windows: फ़ाइल पर डबल-क्लिक करें, Install Certificate चुनें, Local Machine चुनें, फिर Place all certificates in the following store चुनें, और Trusted Root Certification Authorities चुनें।',
        'step_ca_gpo' => 'डोमेन के कई Windows PC: फ़ाइल को Group Policy में एक बार import करें, Computer Configuration → Policies → Windows Settings → Security Settings → Public Key Policies → Trusted Root Certification Authorities के अंतर्गत। Intune इसे Trusted certificate profile के रूप में पुश कर सकता है।',
        'step_ca_mac' => 'Mac: फ़ाइल पर डबल-क्लिक करके उसे Keychain Access में जोड़ें, वहाँ उसे खोलें, और When using this certificate को Always Trust पर सेट करें।',
        'step_ca_firefox' => 'Windows पर Firefox अपने आप Windows के प्रमाणपत्र इस्तेमाल करता है। फिर भी चेतावनी आए तो about:config में security.enterprise_roots.enabled को true करें।',
        'step_ca_safe' => 'यह अथॉरिटी केवल {host} की गारंटी दे सकती है, किसी और की नहीं, इसलिए इसे इंस्टॉल करने से यह किसी दूसरी वेबसाइट का रूप नहीं धर सकती।',
        'step_restart_title' => 'कंटेनर रीस्टार्ट करें',
        'step_restart_body' => 'जिस फ़ोल्डर में आपकी docker-compose.yml है, वहाँ {cmd} चलाएँ।',
        'step_restart_done' => 'हो गया: कंटेनर इस प्रमाणपत्र का उपयोग कर रहा है।',
        'step_open_title' => 'FreeITSM को HTTPS पर खोलें',
        'step_open_body' => '{url} पर जाएँ। अगर वह लोड न हो, तो जाँचें कि आपकी docker-compose.yml पोर्ट 443 प्रकाशित करती है (मानक फ़ाइल उसे 8443 से जोड़ती है)। अगर आपने वह बदला है, तो अपना पोर्ट इस्तेमाल करें।',
        'proxy_heading' => 'रिवर्स प्रॉक्सी के पीछे',
        'proxy_intro' => 'अगर FreeITSM के सामने कोई रिवर्स प्रॉक्सी, लोड बैलेंसर या Cloudflare Tunnel है, तो हर रिक्वेस्ट प्रॉक्सी से FreeITSM तक पहुँचती है। जब तक आप FreeITSM को नहीं बताते कि प्रॉक्सी कौन-सा पता है, वह सबके लिए प्रॉक्सी का पता दर्ज करता है: Reporting → Logs में, ऑडिट ट्रेल में, और जब कोई API key जाँचती है कि कौन-से पते अनुमत हैं।',
        'proxy_off_title' => 'बंद',
        'proxy_off_body' => 'FreeITSM हर कनेक्शन का आने वाला पता दर्ज करता है। जब लोग सीधे FreeITSM से जुड़ते हैं तो यह सही है, और प्रॉक्सी के पीछे गलत - आपके पास कौन-सा है यह देखने के लिए नीचे Test का उपयोग करें।',
        'proxy_on_title' => 'चालू',
        'proxy_on_body' => 'असली पता {header} हेडर से लिया जाता है, लेकिन केवल {list} से आने वाली रिक्वेस्ट पर।',
        'proxy_refused_title' => 'सेट है, लेकिन लागू नहीं',
        'proxy_refused_body' => 'TRUSTED_PROXIES को {list} पर सेट किया गया है, लेकिन कंटेनर शुरू होते समय इसे अस्वीकार कर दिया गया, इसलिए FreeITSM हर कनेक्शन का आने वाला पता दर्ज करता है। कारण देखने के लिए {cmd} चलाएँ।',
        'proxy_wide_title' => 'चेतावनी: यह सेटिंग बहुत व्यापक है',
        'proxy_wide_body' => '{ranges} एक से अधिक प्रॉक्सी को कवर करता है। इसकी हर मशीन अपने को कोई भी पता बता सकती है। TRUSTED_PROXIES को प्रॉक्सी के अपने पते पर बदलें और कंटेनर रीस्टार्ट करें।',
        'proxy_danger_title' => 'गलत सेटिंग क्या करती है - बदलने से पहले इसे पढ़ें',
        'proxy_danger_wide' => 'बहुत व्यापक - खतरनाक गलती। FreeITSM प्रॉक्सी के हेडर का पता केवल आपके सूचीबद्ध पतों से आई रिक्वेस्ट पर मानता है, क्योंकि वह हेडर कोई भी लिख सकता है। अगर आप {example} जैसी रेंज या पूरा Docker नेटवर्क सूचीबद्ध करते हैं, तो उसकी कोई भी मशीन कोई भी पता बता सकती है: वह साइन-इन लॉग और ऑडिट ट्रेल में झूठा पता डाल सकती है, और ऐसी API key को पार कर सकती है जो केवल कुछ पतों को अनुमति देती है। केवल प्रॉक्सी का अपना पता सूचीबद्ध करें।',
        'proxy_danger_missing' => 'सेट नहीं है, जबकि प्रॉक्सी है। कुछ टूटता नहीं, लेकिन हर साइन-इन और हर बदलाव प्रॉक्सी के पते से दर्ज होता है, इसलिए लॉग लोगों में फ़र्क नहीं कर सकते - और API key के अनुमत पते केवल प्रॉक्सी का नाम ले सकते हैं, जिससे उसके ज़रिए आने वाला हर कोई अंदर आ जाता है।',
        'proxy_danger_wrong' => 'गलत पता। हेडर को अनदेखा किया जाता है, इसलिए आप वापस उसी स्थिति में हैं जहाँ सब प्रॉक्सी के रूप में दर्ज होते हैं। Test यह तुरंत दिखा देता है।',
        'proxy_how' => 'यह इस पेज पर नहीं, docker-compose.yml में सेट होता है, और कंटेनर रीस्टार्ट होने पर लागू होता है (docker compose up -d):',
        'proxy_how_cf' => 'Cloudflare Tunnel के लिए {setting} भी सेट करें। कई प्रॉक्सी हों तो उन्हें स्पेस से अलग करें।',
        'proxy_test_heading' => 'Test।',
        'proxy_test_intro' => 'वह पता दिखाता है जो FreeITSM ने अभी आपके लिए दर्ज किया, और उसका मतलब। यह कुछ नहीं बदलता।',
        'proxy_test' => 'Test',
        'proxy_testing' => 'जाँच हो रही है...',
        'proxy_test_failed' => 'जाँच चल नहीं सकी।',
        'proxy_recorded' => 'FreeITSM ने आपका पता यह दर्ज किया',
        'verdict_direct' => 'आप सीधे FreeITSM से जुड़ रहे हैं - कोई प्रॉक्सी हेडर नहीं आया - इसलिए सेट करने को कुछ नहीं है। अगर आपको पता है कि सामने प्रॉक्सी है, तो वह हेडर नहीं जोड़ रही: उसकी सेटिंग देखें।',
        'verdict_off_proxy' => 'FreeITSM के सामने एक प्रॉक्सी है (इस रिक्वेस्ट में {headers} था), और FreeITSM सबके लिए प्रॉक्सी का पता, {ip}, दर्ज कर रहा है। असली पते दर्ज करने के लिए, docker-compose.yml में ऐप के एनवायरनमेंट में यह जोड़ें:',
        'proxy_suggest_then' => 'यह प्रॉक्सी का वह पता है जैसा FreeITSM उसे देखता है - इसे अकेले सूचीबद्ध करें, इससे व्यापक कुछ नहीं। फिर docker compose up -d चलाएँ और दोबारा Test करें।',
        'verdict_working' => 'काम कर रहा है: यह पता प्रॉक्सी के हेडर से आया। जाँचें कि यह वाकई आपके कंप्यूटर का पता है - Windows पर ipconfig इसे दिखाता है; अपने नेटवर्क के बाहर से, आपका सार्वजनिक पता। अगर यह प्रॉक्सी का पता या 127.0.0.1 दिखाए, तो कुछ गलत है।',
        'verdict_too_wide' => 'सुरक्षित नहीं: आपका अपना पता, {ip}, उस रेंज के अंदर है जिसे FreeITSM प्रॉक्सी के रूप में भरोसेमंद मानता है, इसलिए FreeITSM आपको प्रॉक्सी से अलग नहीं कर सकता - और उस रेंज का कोई भी दूसरा व्यक्ति कोई भी पता बता सकता है। TRUSTED_PROXIES को प्रॉक्सी के अपने पते पर बदलें और कंटेनर रीस्टार्ट करें।',
        'verdict_still_proxy' => 'काम नहीं कर रहा: दर्ज पता प्रॉक्सी का ही है, यानी प्रॉक्सी {header} हेडर नहीं भेज रही। प्रॉक्सी से {header} जुड़वाएँ, या TRUSTED_PROXY_HEADER को वही हेडर दें जो वह भेजती है।',
        'verdict_refused' => 'सेटिंग लागू नहीं है (ऊपर देखें), इसलिए FreeITSM हर कनेक्शन का आने वाला पता दर्ज करता है। पहले सेटिंग ठीक करें, फिर दोबारा Test करें।',
        'proxy_headers_seen' => 'इस रिक्वेस्ट पर प्रॉक्सी हेडर:',
        'proxy_headers_none' => 'इस रिक्वेस्ट पर कोई प्रॉक्सी हेडर नहीं।',
