        'caldav_desc' => 'FreeITSM हर विश्लेषक के शेड्यूल किए गए काम को आपके CalDAV सर्वर पर मौजूद एक कैलेंडर में लिखता है, <strong>उस विश्लेषक के रूप में साइन इन होकर</strong>। किसी CalDAV सर्वर में किसी एक अकाउंट के लिए सबके कैलेंडर में लिखने का कोई तरीका नहीं होता, इसलिए यहाँ कोई पासवर्ड नहीं है: हर विश्लेषक <strong>Preferences &rarr; My work calendar</strong> के तहत खुद साइन इन करता है और अपना कैलेंडर चुनता है।',
        'server_url' => 'सर्वर का पता',
