        'subtitle' => 'व्यक्तिगत सेटिंग्स जो आपके खाते में सहेजी जाती हैं — ये हर ब्राउज़र में आपके साथ रहती हैं।',
        'tab_general' => 'सामान्य',
        'tab_notifications' => 'सूचनाएँ',
        'tab_display' => 'डिस्प्ले',
        'tab_details' => 'मेरे विवरण',
        'language_heading' => 'इंटरफ़ेस भाषा',
        'language_desc' => 'FreeITSM UI में इस्तेमाल होने वाली भाषा। आपकी चुनी हुई भाषा में अभी तक अनुवादित न हुए स्ट्रिंग अंग्रेज़ी में दिखाई देते हैं। बदलने पर पेज रीलोड होता है।',
        'saving' => 'सहेजा जा रहा है…',
        'notif_heading' => 'घंटी में',
        'notif_desc' => 'इनमें से कौन-सी चीज़ें स्क्रीन के ऊपर घंटी में दिखाई देंगी। आपको अपनी खुद की कार्रवाइयों के बारे में कभी सूचित नहीं किया जाता, और एक ही टिकट में हुए कई बदलाव एक साथ समूहीकृत कर दिए जाते हैं।',
        'sound_heading' => 'सूचना ध्वनि',
        'sound_desc' => 'जब घंटी में कुछ नया आए, या कोई war room में आपका उल्लेख करे, तो एक छोटी ध्वनि बजाएं। जब तक आप कोई ध्वनि नहीं चुनते, यह बंद रहती है।',
        'sound_off' => 'कोई ध्वनि नहीं',
        'sound_chime' => 'चाइम',
        'sound_ping' => 'पिंग',
        'sound_knock' => 'नॉक',
        'sound_play' => 'चलाएं',
        'sound_note' => 'जब तक आप पेज पर कहीं क्लिक नहीं करते, आपका ब्राउज़र कोई ध्वनि नहीं बजाएगा, इसलिए टैब खोलने के बाद पहली सूचना शायद खामोश रहे। जो सूचनाएँ टैब खोलते समय पहले से प्रतीक्षा में थीं, उनके लिए कुछ भी नहीं सुनाई देगा।',
        'cal_subtasks_heading' => 'कार्य कैलेंडर में उप-कार्य',
        'cal_subtasks_desc' => 'क्या कैलेंडर में कार्यों के साथ उप-कार्य भी दिखाई दें। कैलेंडर के साइडबार में भी यही नियंत्रण है, और दोनों हमेशा मेल खाते रहते हैं।',
        'task_view_heading' => 'कार्य खोलना',
        'task_view_desc' => 'क्या कोई कार्य बोर्ड के किनारे वाले पैनल में खुले, या विवरण और टिप्पणियों के लिए जगह वाली एक बड़ी विंडो में।',
        'task_view_panel' => 'साइड पैनल में',
        'task_view_modal' => 'एक बड़ी विंडो में',
        'task_open_other_desc' => 'तालिका, कैलेंडर और टाइमलाइन से कार्य बगल के पैनल में खुलता है, ताकि आपकी जगह बनी रहे। चुनें कि वह पैनल क्या दिखाए।',
        'task_open_quick' => 'एक झलक - स्थिति, तिथियाँ, असाइनी और विवरण',
        'task_open_full' => 'पूरा कार्य - बोर्ड जैसा ही, उपकार्य, चेकलिस्ट और टिप्पणियों के साथ',
        'desktop_heading' => 'डेस्कटॉप नोटिफ़िकेशन',
        'desktop_desc' => 'बेल से आने वाली हर नई सूचना को आपके कंप्यूटर पर नोटिफ़िकेशन के रूप में दिखाएँ - Windows पर Edge में, Windows नोटिफ़िकेशन - ताकि किसी दूसरी विंडो में काम करते हुए भी आप उसे देखें। इनके आने के लिए FreeITSM का ब्राउज़र टैब में खुला होना ज़रूरी है।',
        'desktop_label' => 'डेस्कटॉप नोटिफ़िकेशन दिखाएँ',
        'desktop_test' => 'जाँचें',
        'desktop_test_title' => 'डेस्कटॉप नोटिफ़िकेशन चालू हैं',
        'desktop_test_body' => 'बेल से आने वाली नई सूचनाएँ ऐसे दिखेंगी।',
        'desktop_ask' => 'इसे चालू करने पर आपका ब्राउज़र पूछेगा कि इस साइट से नोटिफ़िकेशन की अनुमति दें या नहीं।',
        'desktop_allowed' => 'आपका ब्राउज़र इस साइट से नोटिफ़िकेशन की अनुमति दे रहा है।',
        'desktop_blocked' => 'आपका ब्राउज़र इस साइट के नोटिफ़िकेशन ब्लॉक कर रहा है। ब्राउज़र की साइट सेटिंग्स (पते के पास का पैडलॉक) में उन्हें अनुमति दें, फिर इसे चालू करें।',
        'desktop_unsupported' => 'यह ब्राउज़र डेस्कटॉप नोटिफ़िकेशन नहीं दिखा सकता।',
        'desktop_insecure' => 'ब्राउज़र केवल https पर खोली गई साइट पर डेस्कटॉप नोटिफ़िकेशन की अनुमति देते हैं।',
        'task_email_heading' => 'आपको सौंपे गए कार्य',
        'task_email_desc' => 'जब भी कोई कार्य आपको सौंपा जाए तो ईमेल पाएँ - जब आपके लिए बनाया जाए, या किसी और से आपको सौंपा जाए। जो कार्य आप खुद को सौंपते हैं, उसके लिए कुछ नहीं भेजा जाता।',
        'task_email_label' => 'मुझे कार्य सौंपे जाने पर ईमेल करें',
        'board_subtasks_heading' => 'टास्क बोर्ड पर उपकार्य',
        'board_subtasks_desc' => 'उपकार्य वाला कार्य बोर्ड पर अपने कार्ड के नीचे उन्हें सूचीबद्ध करता है। चुनें कि कौन-से - कार्ड हमेशा अपनी गिनती दिखाता है, और गिनती पर क्लिक करने से उस एक कार्ड की सूची दिखती या छिपती है। यही विकल्प Tasks साइडबार में भी है।',
        'board_subtasks_label' => 'सभी पूरे होने पर उन्हें छिपाएँ',
        'board_subtasks_all' => 'सभी उपकार्य',
        'board_subtasks_open' => 'केवल वे जो करने बाकी हैं',
        'board_subtasks_none' => 'कोई नहीं - बस गिनती',
        'work_fold_heading' => 'कार्य पर खाली वर्क सेक्शन',
        'work_fold_desc' => 'किसी कार्य के Work व्यू में चेकलिस्ट, फ़ॉर्म, प्रक्रियाएँ और फ़ॉलो-अप होते हैं। चुनें कि जिसमें कुछ न हो उसे अटैच और बनाएँ कंट्रोल के साथ पूरा दिखाया जाए, या "चेकलिस्ट (0)" जैसे शीर्षक में समेटा जाए जो एक क्लिक से खुलता है।',
        'work_fold_show' => 'उन्हें पूरा दिखाएँ',
        'work_fold_collapse' => 'खाली को शीर्षक में समेटें',
        'nt_company_heading' => 'नए टिकट के लिए मेरी कंपनी',
        'nt_company_desc' => 'सभी-कंपनियों व्यू में, नया टिकट पूछता है कि टिकट किस कंपनी के लिए है। यहाँ एक चुनें ताकि वह आपके लिए चुनी जाए। आप फ़ॉर्म पर इसे फिर भी बदल सकते हैं, और अगर आप उस कंपनी तक अब नहीं पहुँच सकते, तो कुछ नहीं चुना जाता।',
        'nt_company_none' => 'कोई नहीं - मैं हर बार चुनता हूँ',
        'search_dismiss_heading' => 'खोज पैनल बंद करना',
        'search_dismiss_desc' => 'खोज पैनल को रास्ते से हटाकर खुला छोड़ा जा सकता है, इसलिए डिफ़ॉल्ट रूप से केवल इसका ✕ या Escape कुंजी ही इसे बंद करती है। इसे चालू करें ताकि आप जैसे ही कहीं और क्लिक करें — फ़ोल्डर सूची, टिकट सूची या टूलबार पर — यह बंद हो जाए। अभी-अभी मिले टिकट, या उसके गुणों पर क्लिक करने से पैनल फिर भी खुला रहता है, ताकि आप उसके नतीजे पर कार्रवाई करें तो भी खोज बनी रहे।',
        'search_dismiss_label' => 'जब मैं कहीं और क्लिक करूँ तो इसे बंद करें',
        'section_memory_heading' => 'मॉड्यूल में वापस आना',
        'section_memory_desc' => 'जब आप मेनू, होम पेज या Ctrl+K से कोई मॉड्यूल खोलते हैं, तो उसके फ़्रंट पेज के बजाय वहाँ अंतिम उपयोग किए गए सेक्शन पर जाएँ - जैसे Assets → Servers। किसी खास पेज या रिकॉर्ड के लिंक फिर भी ठीक वही खोलते हैं। इस ब्राउज़र में याद रखा जाता है।',
        'section_memory_label' => 'हर मॉड्यूल का अंतिम सेक्शन दोबारा खोलें',
        'remember_company_heading' => 'साइन-इन पर कंपनी',
        'remember_company_desc' => 'हर साइन-इन उस कंपनी में शुरू करें जिसे आपने कंपनी स्विचर में (या सभी कंपनियाँ में) अंतिम बार चुना था, डिफ़ॉल्ट कंपनी के बजाय। जो कंपनी आप अब नहीं देख सकते, या जो निष्क्रिय कर दी गई है, छोड़ दी जाती है। नए टिकट उस कंपनी में दर्ज होते हैं जिसमें आप काम कर रहे हैं, इसलिए बनाने से पहले स्विचर जाँच लें।',
        'remember_company_label' => 'मेरी अंतिम उपयोग की गई कंपनी में शुरू करें',
        'landing_heading' => 'प्रारंभ पृष्ठ',
        'workcal_heading' => 'मेरा कार्य कैलेंडर',
        'taskcal_heading' => 'इस कैलेंडर में कार्य',
        'taskcal_off' => 'कोई नहीं',
        'taskcal_work' => 'जब मैं इसे करने की योजना बनाऊं',
        'taskcal_due' => 'जब यह नियत हो',
        'taskcal_both' => 'दोनों',
        'taskcal_note' => 'एक कार्य आपके कैलेंडर में दो चीज़ें डाल सकता है: वह समय जो आपने इसे करने के लिए तय किया है, एक सामान्य अपॉइंटमेंट के रूप में, और इसकी नियत तिथि, एक पूरे दिन की प्रविष्टि के रूप में। पूर्ण हो चुके कार्य हटा दिए जाते हैं, और किसी टीम को सौंपा गया कार्य — न कि आपको — कभी नहीं जोड़ा जाता।',
        'taskcal_failed' => 'वह विकल्प सहेजा नहीं जा सका',
        'workcal_desc' => 'आपके शेड्यूल किए गए टिकट उस कैलेंडर में डालें जिसे आप वास्तव में उपयोग करते हैं — Google, Apple, Outlook या कोई भी अन्य ऐप जो कैलेंडर की सदस्यता ले सकता हो।',
        'workcal_off' => 'बंद',
        'workcal_feed' => 'सदस्यता लिंक',
        'workcal_push' => 'मेरे कैलेंडर में जोड़ें',
        'workcal_push_none' => 'टिकट सीधे आपके कैलेंडर में जोड़ना उपलब्ध नहीं है: इस सिस्टम पर अभी तक किसी व्यवस्थापक ने कैलेंडर कनेक्शन सेट अप नहीं किया है।',
        'workcal_push_where' => 'आपके शेड्यूल किए गए टिकट {addr} के कैलेंडर में लिखे जाएंगे।',
        'workcal_push_bad' => '{addr} के लिए कोई कैलेंडर नहीं मिल सका। यह आपके FreeITSM खाते पर मौजूद पता है, और यह हमेशा आपका मेलबॉक्स नहीं होता — किसी व्यवस्थापक से अपना कैलेंडर सिंक सही पते पर सेट करने के लिए कहें।',
        'workcal_push_noaddr' => 'हमें नहीं पता कि आपका मेलबॉक्स कौन-सा है। किसी व्यवस्थापक से इसे System → Calendar sync में सेट करने के लिए कहें।',
        'workcal_conn' => 'कौन-सा कैलेंडर',
        'workcal_conn_choose' => 'चुनें…',
        'workcal_conn_needed' => 'चुनें कि आपका शेड्यूल किया हुआ काम किस कैलेंडर में जाना चाहिए।',
        'workcal_push_caldav_where' => 'आपके शेड्यूल किए गए टिकट आपके कैलेंडर “{name}” में लिखे जाएँगे।',
        'caldav_intro' => '{server} पर अपने कैलेंडर में साइन इन करें और चुनें कि आपका शेड्यूल किया हुआ काम किस कैलेंडर में जाना चाहिए। FreeITSM आपके रूप में साइन इन करता है, इसलिए यह केवल उन्हीं कैलेंडर तक पहुँच सकता है जिन तक आप पहुँच सकते हैं।',
        'caldav_username' => 'उपयोगकर्ता नाम',
        'caldav_password' => 'पासवर्ड',
        'caldav_password_hint' => 'आपका कैलेंडर पासवर्ड, या अगर आपका कैलेंडर ऐप पासवर्ड देता है तो वह - यही ज़्यादा सुरक्षित विकल्प है। एन्क्रिप्टेड रूप में संग्रहीत और फिर कभी नहीं दिखाया जाता।',
        'caldav_password_saved' => 'सहेजा गया - इसे बनाए रखने के लिए खाली छोड़ें',
        'caldav_find' => 'ढूँढें',
        'caldav_finding' => 'आपके कैलेंडर ढूँढे जा रहे हैं…',
        'caldav_choose' => 'कैलेंडर',
        'caldav_none' => 'वह साइन-इन काम कर गया, लेकिन इसमें ऐसा कोई कैलेंडर नहीं है जिसमें घटनाएँ रखी जा सकें।',
        'caldav_needs' => 'साइन इन करें और एक कैलेंडर चुनें। इसे सहेजने से यह चालू हो जाता है।',
        'caldav_saved' => 'सहेजा गया। आपका शेड्यूल किया हुआ काम “{name}” में जाता है।',
        'caldav_saved_error' => 'सहेजा गया, लेकिन कैलेंडर में लिखना विफल रहा: {error}',
        'caldav_current' => '{user} के रूप में साइन इन है, “{name}” में लिख रहा है।',
        'caldav_change' => 'बदलें',
        'caldav_forget' => 'भुलाएँ',
        'caldav_forget_title' => 'अपना कैलेंडर साइन-इन भुला दें?',
        'caldav_forget_confirm' => 'FreeITSM अपनी घटनाओं को आपके कैलेंडर से वापस निकाल लेता है, फिर आपका साइन-इन भुला देता है और इसे बंद कर देता है।',
        'workcal_disabled' => 'इस सिस्टम पर किसी व्यवस्थापक ने कैलेंडर सदस्यता लिंक बंद कर दिए हैं।',
        'workcal_url' => 'आपका निजी सदस्यता लिंक',
        'workcal_show' => 'अपना लिंक पाएं',
        'workcal_copy' => 'कॉपी करें',
