    'security' => [
        'title' => 'सुरक्षा',
        'subtitle' => 'प्रमाणीकरण नीतियाँ और खाता सुरक्षा कॉन्फ़िगर करें',
        'selfreg_heading' => 'स्व-सेवा पंजीकरण',
        'selfreg_desc' => 'क्या लोग साइन-इन पेज से अपना स्व-सेवा पोर्टल खाता खुद बना सकते हैं। डिफ़ॉल्ट रूप से यह बंद रहता है। चालू होने पर भी, पासवर्ड सेट होने से पहले साइन-अप को ईमेल लिंक से कन्फ़र्म करना ज़रूरी है।',
        'selfreg_label' => 'स्व-पंजीकरण की अनुमति दें',
        'selfreg_hint' => 'बंद = कोई भी खुद अपना खाता नहीं बना सकता। आपके द्वारा जोड़े गए लोग फिर भी साइन इन कर सकते हैं — वे पोर्टल के साइन-इन पेज पर “Forgot your password?” का उपयोग करके अपना पहला पासवर्ड सेट करते हैं।',
        'trusted_heading' => 'विश्वसनीय डिवाइस',
