        'trust_duration' => 'विश्वास अवधि',
        'trust_duration_hint' => 'OTP सत्यापन के बाद डिवाइस कितने समय तक विश्वसनीय रहता है',
        'password_heading' => 'पासवर्ड नीति',
        'password_desc' => 'उपयोगकर्ताओं को समय-समय पर अपना पासवर्ड बदलने के लिए बाध्य करें। पासवर्ड की अवधि समाप्त होने पर, अगली बार लॉगिन करते समय उपयोगकर्ता को अनिवार्य रूप से पासवर्ड बदलने वाली स्क्रीन पर भेज दिया जाता है। बंद करने के लिए 0 सेट करें।',
        'password_expiry' => 'पासवर्ड समाप्ति',
        'password_expiry_hint' => 'पासवर्ड बदलने से पहले उसकी अधिकतम आयु',
        'lockout_heading' => 'खाता लॉकआउट',
        'lockout_desc' => 'ब्रूट-फ़ोर्स हमलों को रोकने के लिए बार-बार असफल लॉगिन प्रयासों के बाद खाते लॉक करें। लॉकआउट बंद करने के लिए अधिकतम प्रयास 0 सेट करें।',
        'max_attempts' => 'अधिकतम असफल प्रयास',
        'max_attempts_hint' => 'खाता लॉक होने से पहले गलत पासवर्ड की संख्या',
        'lockout_duration' => 'लॉकआउट अवधि',
        'lockout_duration_hint' => 'खाता कितने समय तक लॉक रहता है (अनलॉक होने के बाद काउंटर रीसेट हो जाता है)',
        'ipban_heading' => 'IP बैन',
        'ipban_desc' => 'उन IP पतों को अपने आप बैन करें जो बार-बार ऐसे खातों में लॉगिन करने की कोशिश करते हैं जो मौजूद ही नहीं हैं या लॉक हैं। हर बैन 24 घंटे तक चलता है। हर बैन के बाद थ्रेशोल्ड 1 कम हो जाता है (न्यूनतम तक), जिससे बार-बार गड़बड़ी करने वालों के लिए दुरुपयोग करना मुश्किल हो जाता है। बंद करने के लिए अधिकतम प्रयास 0 सेट करें।',
        'first_ban' => 'पहला बैन थ्रेशोल्ड',
