        'min_threshold' => 'न्यूनतम थ्रेशोल्ड',
        'min_threshold_hint' => 'यह थ्रेशोल्ड इस न्यूनतम सीमा तक पहुँचने के बाद घटना बंद हो जाता है',
        'ipban_example_strong' => 'उदाहरण:',
