        'allowed_extensions_hint' => 'FreeITSM जिसे भी सुरक्षित मानता है उसे स्वीकार करने के लिए इसे खाली छोड़ दें, इसमें भविष्य के अपडेट में जोड़े जाने वाले नए प्रकार भी शामिल हैं। कम स्वीकार करने के लिए, केवल वे एक्सटेंशन सूचीबद्ध करें जो आप चाहते हैं, कॉमा से अलग करके।',
        'allowed_extensions_ph' => 'जैसे pdf, docx, xlsx, png, jpg',
        'allowed_extensions_note' => 'आप इस सूची को केवल संकीर्ण (कम) कर सकते हैं। जिस एक्सटेंशन को FreeITSM पहले से सुरक्षित नहीं मानता, उसे नज़रअंदाज़ कर दिया जाता है, इसलिए यहाँ कुछ भी लिखने से कोई प्रोग्राम या स्क्रिप्ट स्वीकार्य नहीं बन सकती।',
        'rejected_note' => 'किसी भी स्थिति में, टिकट में बताया जाता है कि क्या हुआ और क्यों, ताकि किसी को यह सोचना न पड़े कि उनकी फ़ाइल कहाँ गई।',
        'max_attachment' => 'सबसे बड़ा अनुलग्नक',
