        'max_total' => 'सबसे बड़ा ईमेल',
        'max_total_hint' => 'एक आने वाले ईमेल के सभी अनुलग्नक मिलाकर। 0 का मतलब ऊपर वाली सीमा से आगे कोई सीमा नहीं।',
        'php_limits' => 'इस सर्वर पर PHP ब्राउज़र अपलोड प्रति फ़ाइल {upload} और प्रति अनुरोध {post} तक स्वीकार करता है (php.ini में upload_max_filesize और post_max_size), और उसके पास काम करने के लिए {memory} मेमोरी है। जिस फ़ाइल को PHP नकार दे वह FreeITSM तक कभी नहीं पहुँचती, इसलिए इनसे ऊपर की सीमा केवल ईमेल के काम आती है। सामने मौजूद वेब सर्वर या प्रॉक्सी (nginx client_max_body_size, IIS maxAllowedContentLength) अपनी कम सीमा भी तय कर सकते हैं।',
        'php_limits_warn' => 'सबसे बड़ा अनुलग्नक उससे ज़्यादा है जो PHP ब्राउज़र से स्वीकार करता है: php.ini में upload_max_filesize और post_max_size भी बढ़ाएँ, वरना FreeITSM के ज़रिए अपलोड की गई फ़ाइलें पहुँचने से पहले ही अस्वीकार हो जाएँगी।',
