        'signout_heading' => 'साइन-आउट पते',
        'signout_desc' => 'दोनों को हर आइडेंटिटी प्रोवाइडर में अनुमत साइन-आउट (पोस्ट-लॉगआउट) रीडायरेक्ट URL के रूप में रजिस्टर करें। FreeITSM से साइन आउट करने पर लोग प्रोवाइडर से भी साइन आउट हो जाते हैं, जो फिर उन्हें इनमें से किसी एक पते पर वापस भेजता है। Keycloak और Okta ऐसा कोई भी पता अस्वीकार कर देते हैं जो ठीक इसी रूप में सूचीबद्ध नहीं है।',
