        'carddav_write_heading' => 'बदलाव वापस भेजना',
        'carddav_write_hint' => 'सामान्यतः FreeITSM सिर्फ इस address book को पढ़ता है। इसे चालू करें, तो किसी contact के पद, विभाग, कार्यालय, फ़ोन या मोबाइल में विश्लेषक द्वारा किया गया बदलाव उनके contact card में भी लिख दिया जाता है। उनकी कर्मचारी ID और मैनेजर FreeITSM में ही रहते हैं, क्योंकि contact card में इन्हें रखने की कोई जगह नहीं होती।',
