        'carddav_allow_create_hint' => 'डिफ़ॉल्ट रूप से बंद। इसे चालू करने पर, जो व्यक्ति किसी address book में नहीं है उसे Tickets और Assets में एक Add to address book बटन मिलता है, जो यहाँ उनका कार्ड बनाता है और उन्हें लिंक कर देता है। कुछ भी लिखने से पहले FreeITSM जाँचता है कि book में पहले से किसी के पास उनका ईमेल पता नहीं है, और उसके बाद जाँचता है कि नया कार्ड वही है जिसे यह स्रोत import करता है - वह टैग या समूह जोड़कर जिससे यह import करता है - और अगर ऐसा नहीं है तो उसे फिर से हटा देता है।',
        'carddav_write_warning' => 'सिर्फ ऊपर सूचीबद्ध जानकारी बदली जाती है, और सिर्फ उस contact पर जिसे संपादित किया जा रहा है। card पर बाकी सब कुछ — फ़ोटो, नोट्स, जन्मदिन, पूरा पता, groups — बिल्कुल वैसा ही रहता है। अगर FreeITSM के पिछले import के बाद किसी ने address book में वही जानकारी बदल दी है, तो उनके बदलाव को मिटाने के बजाय यह बदलाव अस्वीकार कर दिया जाता है।',
