        'maint_page_title' => 'इम्पोर्ट किए गए लोग',
        'maint_page_sub' => 'डायरेक्टरी स्रोत - LDAP, एड्रेस बुक या Microsoft Entra ID - द्वारा इम्पोर्ट किए गए लोग, जब उन पर निर्णय की ज़रूरत हो: उनका स्रोत हटा दिया गया, वह उन्हें अब नहीं लाता, या उन्हें कभी इम्पोर्ट नहीं किया जाना चाहिए था। जिनके टिकट या उपकरण हैं उन्हें कभी नहीं हटाया जाता, और यहाँ किया गया हर काम सिस्टम लॉग में दर्ज होता है।',
        'maint_source_heading' => 'एक स्रोत',
        'maint_source_label' => 'स्रोत',
        'maint_deleted_kind' => 'हटाया गया',
        'maint_deleted_hint' => 'यह स्रोत हटा दिया गया है, इसलिए यह अब किसी को नहीं लाता। इसके इम्पोर्ट से बनाए गए लोग नीचे सूचीबद्ध हैं, जब तक कि कोई अन्य स्रोत उन्हें अब अद्यतन न रखता हो। जिन्हें इसने यहाँ पहले से मौजूद किसी व्यक्ति से मिलाया था, वे सूचीबद्ध नहीं हैं।',
