        'maint_orphans_desc' => 'ऐसे स्रोत द्वारा इम्पोर्ट किए गए जो अब मौजूद नहीं है। अब कुछ भी उन्हें लॉक या अपडेट नहीं करता; तय करें कि उन्हें सामान्य लोगों के रूप में रखना है, छोड़ चुके (leaver) चिह्नित करना है, या हटाना है।',
        'maint_stale_heading' => 'वे लोग जिन्हें यह स्रोत अब नहीं लाता',
        'maint_stale_hint' => 'हर इम्पोर्ट हर व्यक्ति के अंतिम बार मिलने की तिथि दर्ज करता है। ये लोग अभी भी इस स्रोत को सौंपे गए हैं, लेकिन आपके चुने समय तक यह उन्हें नहीं पा सका है: उन्हें डायरेक्टरी से हटाया गया हो सकता है, इम्पोर्ट के दायरे से बाहर किया गया हो सकता है, या इम्पोर्ट का चलना बंद हो गया हो सकता है। उन्हें छोड़ चुके (leaver) चिह्नित करें, सामान्य लोगों के रूप में रखें जिन्हें यह स्रोत अब नहीं सँभालता, या हटाएँ।',
