        'mcp_desc' => 'FreeITSM <strong>Model Context Protocol</strong> समझता है, इसलिए Claude Code या Claude Desktop जैसा AI असिस्टेंट इसे पढ़ सकता है - प्रोजेक्ट, खुली घटनाएँ, सेवा स्थिति, परिवर्तन, एसेट और बहुत कुछ। यह <strong>केवल-पढ़ने योग्य</strong> है और वही देखता है जो कुंजी का विश्लेषक देख सकता है: उसके मॉड्यूल, और कुंजी की कंपनियाँ। नीचे <strong>MCP server</strong> अनुमति के साथ एक कुंजी बनाएँ और असिस्टेंट को यह पता दें। <a href="https://github.com/edmozley/freeitsm/wiki/MCP-Server" target="_blank" rel="noopener">गाइड</a> देखें।',
