        'del_attempts_help' => 'विफल प्रयास को 1 मिनट बाद, फिर 5 मिनट, 15 मिनट, 1 घंटे और 6 घंटे बाद, फिर हर 6 घंटे में दोबारा आज़माया जाता है। अंतिम प्रयास के बाद डिलीवरी को <strong>Dead</strong> चिह्नित किया जाता है और वह <em>Replay</em> की प्रतीक्षा करती है। बदलाव अब से कतार में लगने वाले वेबहुक पर लागू होता है - कतार में पहले से मौजूद वेबहुक उसी संख्या पर रहते हैं जिससे वे शुरू हुए थे।',
