        'del_int_label' => 'यदि भेजना बीच में कट गया',
        'del_int_retry' => 'दोबारा आज़माएँ - एंडपॉइंट को यह दो बार मिल सकता है',
        'del_int_stop' => 'रुकें, और इसे Replay के लिए छोड़ दें',
        'del_int_help' => 'यदि भेजने के बीच में वर्कर रुक जाता है - सर्वर रीस्टार्ट, या शेड्यूल्ड टास्क का बंद होना - तो कोई नहीं जानता कि एंडपॉइंट को यह मिला या नहीं। 10 मिनट बाद FreeITSM इसे निपटाता है: <strong>Try again</strong> इसे विफल प्रयास गिनकर ऊपर दिए शेड्यूल पर दोबारा आज़माता है; <strong>Stop</strong> इसे तुरंत Dead चिह्नित कर देता है, ताकि आप एंडपॉइंट जाँच सकें और खुद Replay कर सकें। हर भेजने में <code>X-FreeITSM-Delivery</code> हेडर होता है, जिसमें हर प्रयास और Replay पर वही संख्या रहती है, इसलिए आपका अपना चलाया रिसीवर दोहराव को अनदेखा कर सकता है। Slack और Teams जैसे चैट टूल ऐसा नहीं कर सकते, और संदेश दो बार दिखाएँगे।',
        'dp_title' => 'डेटा सुरक्षा',
        'dp_desc' => 'FreeITSM आपके webhooks के बारे में डिस्क पर क्या रखता है, और कितने समय तक।',
        'enc_on_title' => 'Webhook URL और साइनिंग सीक्रेट संग्रहीत रूप में एन्क्रिप्टेड हैं',
        'enc_on_body' => 'AES-256-GCM के साथ संग्रहीत, वर्कफ़्लो में भी और डिलीवरी क्यू में भी। webhook URL अपने आप में एक क्रेडेंशियल है &mdash; जिसके पास यह है वह आपके चैनल पर पोस्ट कर सकता है &mdash; और साइनिंग सीक्रेट ही साबित करता है कि संदेश वाकई आपकी ओर से आया है।',
        'enc_off_title' => 'कोई एन्क्रिप्शन कुंजी कॉन्फ़िगर नहीं है &mdash; webhook URL और साइनिंग सीक्रेट सादे टेक्स्ट में संग्रहीत हैं',
        'enc_off_body' => 'एन्क्रिप्शन कुंजी फ़ाइल मौजूद होने पर FreeITSM इन्हें एन्क्रिप्ट करता है, लेकिन इस इंस्टॉल में कोई नहीं है, इसलिए आपके webhooks को सीधे विफल करने के बजाय इन्हें जैसे-का-तैसा सहेजा जा रहा है। जो कोई डेटाबेस या उसका बैकअप पढ़ सकता है, वह आपके चैनलों पर पोस्ट कर सकता है और आपके सिग्नेचर बना सकता है। एन्क्रिप्शन कुंजी (<code>ENCRYPTION_KEY_PATH</code>) कॉन्फ़िगर करें और संग्रहीत मान एन्क्रिप्ट करने के लिए हर webhook वर्कफ़्लो को फिर से सहेजें।',
        'ret_label' => 'भेजे गए payload कितने समय तक रखें',
        'ret_none' => 'इन्हें बिल्कुल न रखें',
        'ret_1' => '1 दिन',
        'ret_7' => '7 दिन (अनुशंसित)',
        'ret_30' => '30 दिन',
        'ret_forever' => 'जब तक डिलीवरी रिकॉर्ड रहता है',
        'ret_help' => 'डिलीवरी लॉग ठीक वही payload संग्रहीत करता है जो भेजा गया था। <strong>Full record</strong> फ़ॉर्मैट के साथ वह एक <strong>पूरा टिकट</strong> होता है &mdash; विषय, अनुरोधकर्ता, सब कुछ &mdash; यहाँ सादे टेक्स्ट में कॉपी किया हुआ। इतने दिनों के बाद payload और response बॉडी हटा दी जाती हैं, जबकि डिलीवरी <em>रिकॉर्ड</em> (एंडपॉइंट, स्थिति, समय, त्रुटियाँ) ऑडिट के लिए तब तक रखा जाता है जब तक ऊपर दिया गया लॉग रिटेंशन ({days} दिन) पूरी पंक्ति को हटा नहीं देता।',
        'ret_tradeoff' => '<strong>समझौता:</strong> <em>Replay</em> संग्रहीत payload को दोबारा भेजता है, इसलिए जिस डिलीवरी का payload हटाया जा चुका है उसे अब Replay नहीं किया जा सकता। Replay आमतौर पर किसी विफलता के कुछ घंटों के भीतर उपयोग होता है, हफ़्तों बाद नहीं।',
