    'bingo' => [
        'heading' => 'Feature Bingo',
        'intro' => 'ज़्यादातर लोग अपने पास मौजूद सुविधाओं का एक छोटा हिस्सा ही इस्तेमाल करते हैं। हर कार्ड FreeITSM की एक क्षमता है, और यहाँ सेट अप होते ही उसका सितारा जल उठता है। किसी को खोलकर देखें कि वह क्या है, उसे करना क्यों फ़ायदेमंद है, और उसे कहाँ सेट अप करना है। जो आप कभी इस्तेमाल नहीं करेंगे: उसे "हमारे लिए नहीं" चिह्नित करें और वह स्कोर से बाहर हो जाएगा।',
