    'managers' => [
        'heading' => 'प्रबंधक',
        'intro' => 'प्रबंधक सेल्फ-सर्विस पोर्टल का वह व्यक्ति है जो अपने प्रबंधन वाले लोगों द्वारा बनाए गए टिकट देख सकता है - जैसे किसी विभाग का प्रमुख। उन्हें पोर्टल में <strong>टीम टिकट</strong> टैब मिलता है। सर्विस डेस्क पर इसका असर नहीं होता।',
        'needs_verify' => 'पहले सिस्टम → डेटाबेस सत्यापन चलाएँ। जब तक यह नहीं चलता, यहाँ जो भी सेट हो, प्रबंधक बंद रहते हैं, क्योंकि गोपनीय टिकटों को अलग पहचाना नहीं जा सकता।',
        'on_heading' => 'पोर्टल में प्रबंधक',
