        'source_heading' => 'प्रबंधक कहाँ से आते हैं',
        'source_desc' => 'दो स्रोत, दोनों एक साथ। प्रबंधन पंक्तियाँ हर प्रबंधक के लिए टिकट → उपयोगकर्ता या एसेट → उपयोगकर्ता के प्रबंधक एक्सेस बटन से सेट की जाती हैं।',
