        'conf_stub' => 'कि कोई गोपनीय टिकट मौजूद है',
        'conf_stub_desc' => '"गोपनीय टिकट" के रूप में उसके नंबर और स्थिति के साथ सूचीबद्ध, और उसमें लिखा कुछ नहीं। ध्यान रहे कि अकेले इससे भी प्रबंधक जान सकता है कि किसी ने कुछ निजी उठाया है।',
